// Dub's edge link lookup (apps/web/lib/planetscale/connection.ts and get-link-via-edge.ts at 7e0101363b2a): the
// unchanged @planetscale/database connect({ url }) on PLANETSCALE_DATABASE_URL, SQL with ? parameters.
import assert from 'node:assert/strict';
import { connect } from '@planetscale/database';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const conn = connect({ url: process.env.PLANETSCALE_DATABASE_URL || process.env.DATABASE_URL });
const getLinkViaEdge = async ({ domain, key }) => {
  const { rows } = (await conn.execute('SELECT * FROM Link WHERE domain = ? AND `key` = ?', [domain, key])) || {};
  if (!rows || !Array.isArray(rows) || rows.length === 0) return null;
  return rows[0];
};

if (process.argv[2] === 'readback') {
  const link = await getLinkViaEdge({ domain: 'dub.sh', key: 'launch' });
  assert.equal(link?.url, 'https://kiln.media/launch');
  assert.equal(link.clicks, 1);
  assert.equal(await getLinkViaEdge({ domain: 'dub.sh', key: 'draft' }), null);
  console.log(JSON.stringify({ retained: true, id: link.id, url: link.url, clicks: link.clicks }));
} else {
  // the schema Dub's migration makes (a subset of its Link model)
  await conn.execute('CREATE TABLE Link (id VARCHAR(191) NOT NULL, domain VARCHAR(190) NOT NULL, `key` VARCHAR(190) NOT NULL, url TEXT NOT NULL, clicks INT NOT NULL DEFAULT 0, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (id), UNIQUE KEY Link_domain_key_key (domain, `key`))');
  const inserted = await conn.execute('INSERT INTO Link (id, domain, `key`, url) VALUES (?, ?, ?, ?)', ['link_1', 'dub.sh', 'launch', 'https://kiln.media/launch']);
  assert.equal(inserted.rowsAffected, 1);
  // a duplicate short link is MySQL's unique-key violation, as Prisma's adapter reads it
  const duplicate = await conn.execute('INSERT INTO Link (id, domain, `key`, url) VALUES (?, ?, ?, ?)', ['link_2', 'dub.sh', 'launch', 'https://example.com']).then(() => null, (e) => e);
  assert.match(String(duplicate?.message), /errno 1062/);
  // a click counted and a draft link abandoned, each in its own transaction
  await conn.transaction(async (tx) => { await tx.execute('UPDATE Link SET clicks = clicks + 1 WHERE id = ?', ['link_1']); });
  await conn.transaction(async (tx) => {
    await tx.execute('INSERT INTO Link (id, domain, `key`, url) VALUES (?, ?, ?, ?)', ['link_3', 'dub.sh', 'draft', 'https://kiln.media/draft']);
    throw new Error('the draft was abandoned');
  }).catch((e) => assert.equal(e.message, 'the draft was abandoned'));
  const link = await getLinkViaEdge({ domain: 'dub.sh', key: 'launch' });
  assert.equal(link?.id, 'link_1');
  assert.equal(link.url, 'https://kiln.media/launch');
  assert.equal(link.clicks, 1);
  assert.equal(await getLinkViaEdge({ domain: 'dub.sh', key: 'draft' }), null);
  console.log(JSON.stringify({ id: link.id, url: link.url, clicks: link.clicks }));
}
